#!/usr/bin/env bash
# Regenerates .claude/commands/, .claude/skills/, .claude/agents/, and
# CLAUDE.md from .agents/ so Claude Code can discover them natively.
#
# .agents/ stays the single source of truth. Every generated file is a thin
# pointer back to its .agents/ source — do not hand-edit anything under
# .claude/commands/, .claude/skills/, .claude/agents/, or CLAUDE.md; edit
# the .agents/ file and rerun this script instead.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
AGENTS_DIR="$ROOT/.agents"
CLAUDE_DIR="$ROOT/.claude"

extract_field() {
  # First "<field>:" line inside the leading YAML frontmatter block only.
  sed -n '/^---$/,/^---$/p' "$1" | sed -n "s/^$2: *//p" | head -1
}
extract_description() { extract_field "$1" description; }

rm -rf "$CLAUDE_DIR/commands" "$CLAUDE_DIR/skills" "$CLAUDE_DIR/agents" "$CLAUDE_DIR/rules"
mkdir -p "$CLAUDE_DIR/commands" "$CLAUDE_DIR/skills" "$CLAUDE_DIR/agents" "$CLAUDE_DIR/rules"

# Rules are copied (not pointed to): they are small, and a copy lets Claude
# Code's `paths:` frontmatter load each rule only when a matching file is
# touched. A rule without `paths:` loads every session, so keep those rare.
echo "Generating .claude/rules/ from .agents/rules/ ..."
while IFS= read -r rule_file; do
  rel="${rule_file#"$AGENTS_DIR/rules/"}"
  out="$CLAUDE_DIR/rules/$rel"
  mkdir -p "$(dirname "$out")"
  awk -v src=".agents/rules/$rel" '
    NR==1 && $0=="---" { infm=1; print; next }
    infm && $0=="---"  { infm=0; print; print ""; print "<!-- GENERATED from " src " by .agents/hooks/sync-claude-native.sh — edit the source, not this file. -->"; next }
    { print }
  ' "$rule_file" > "$out"
  grep -q '^paths:' "$rule_file" || echo "  WARNING: $rel has no paths: frontmatter, so it loads in every session"
  echo "  rules/$rel"
done < <(find "$AGENTS_DIR/rules" -type f -name '*.md' | sort)

echo "Generating .claude/commands/ from .agents/commands/ ..."
for cmd_file in "$AGENTS_DIR"/commands/*.md; do
  name="$(basename "$cmd_file" .md)"
  description="$(extract_description "$cmd_file")"
  out="$CLAUDE_DIR/commands/$name.md"
  cat > "$out" <<EOF
---
description: ${description}
---

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — do not edit by hand. -->

Follow the instructions in \`.agents/commands/$name.md\` exactly, step by step.
EOF
  echo "  /$name -> .agents/commands/$name.md"
done

echo "Generating .claude/skills/ from .agents/skills/ ..."
for skill_dir in "$AGENTS_DIR"/skills/*/; do
  name="$(basename "$skill_dir")"
  skill_file="$skill_dir/SKILL.md"
  [ -f "$skill_file" ] || continue
  description="$(extract_description "$skill_file")"

  out_dir="$CLAUDE_DIR/skills/$name"
  mkdir -p "$out_dir"
  cat > "$out_dir/SKILL.md" <<EOF
---
name: ${name}
description: ${description}
user-invocable: false
---

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — do not edit by hand. -->

Follow the instructions in \`.agents/skills/$name/SKILL.md\` exactly.
EOF
  echo "  /$name -> .agents/skills/$name/SKILL.md"
done

echo "Generating .claude/agents/ from .agents/agents/ (subagent: true only) ..."
subagent_names=()
for agent_file in "$AGENTS_DIR"/agents/*.md; do
  name="$(basename "$agent_file" .md)"
  is_subagent="$(extract_field "$agent_file" subagent)"
  [ "$is_subagent" = "true" ] || continue

  description="$(extract_description "$agent_file")"
  tools="$(extract_field "$agent_file" tools)"
  subagent_names+=("$name")

  out="$CLAUDE_DIR/agents/$name.md"
  cat > "$out" <<EOF
---
name: ${name}
description: ${description}
tools: ${tools}
---

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — do not edit by hand. -->

Read \`.agents/agents/$name.md\` for your full role, inputs, outputs, and checklist. Read every file listed under its "## Inputs" section before starting, and apply them exactly — do not invent additional rules.

Report your result using that file's "## Outputs" and "## Checklist" sections as your contract.
EOF
  echo "  subagent $name -> .agents/agents/$name.md"
done

echo "Generating CLAUDE.md ..."
SUBAGENT_LIST=""
for n in "${subagent_names[@]}"; do
  SUBAGENT_LIST="${SUBAGENT_LIST:+$SUBAGENT_LIST, }\`$n\`"
done
cat > "$ROOT/CLAUDE.md" <<EOF
@AGENTS.md
@.agents/CORE.md

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — edit .agents/ sources and rerun the script. -->

## Claude Code wiring

- \`/name\` commands, skills, rules and subagents (${SUBAGENT_LIST}) are generated into \`.claude/\` from \`.agents/\`. Never hand-edit generated files.
- Hooks live in \`.claude/settings.json\` (hand-maintained, not generated).
EOF
echo "  CLAUDE.md"

echo "Done."
